CREATE TABLE public.merchant_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES public.profiles(id),recipient_id uuid NOT NULL REFERENCES public.profiles(id),request_id uuid NOT NULL,reference text NOT NULL UNIQUE,currency text NOT NULL,amount numeric NOT NULL CHECK(amount>0),reason text NOT NULL,sender_name text NOT NULL,recipient_name text NOT NULL,sender_balance_before numeric NOT NULL,sender_balance_after numeric NOT NULL,recipient_balance_before numeric NOT NULL,recipient_balance_after numeric NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sender_id,request_id),CHECK(sender_id<>recipient_id));
GRANT SELECT ON public.merchant_transfers TO authenticated;
GRANT ALL ON public.merchant_transfers TO service_role;
ALTER TABLE public.merchant_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants and finance read transfers" ON public.merchant_transfers FOR SELECT TO authenticated USING(auth.uid() IN (sender_id,recipient_id) OR public.has_permission(auth.uid(),'finance'));
CREATE INDEX merchant_transfers_sender_date ON public.merchant_transfers(sender_id,created_at DESC);
CREATE INDEX merchant_transfers_recipient_date ON public.merchant_transfers(recipient_id,created_at DESC);
CREATE FUNCTION public.find_transfer_recipient(p_identifier text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE p public.profiles; m public.merchant_profiles; n integer;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'An active ObPay account is required.'; END IF;
 IF p_identifier IS NULL OR length(trim(p_identifier))<3 OR length(trim(p_identifier))>160 THEN RAISE EXCEPTION 'Enter the recipient username, email or account ID.'; END IF;
 SELECT count(*) INTO n FROM public.profiles pr WHERE pr.status='active' AND (lower(pr.email)=lower(trim(p_identifier)) OR pr.id::text=trim(p_identifier) OR EXISTS(SELECT 1 FROM public.merchant_profiles mp WHERE mp.user_id=pr.id AND (lower(mp.merchant_slug)=lower(trim(p_identifier)) OR mp.merchant_id=trim(p_identifier))));
 IF n<>1 THEN RAISE EXCEPTION 'No unique active merchant matches that account. Use the exact username, email or account ID.'; END IF;
 SELECT * INTO p FROM public.profiles pr WHERE pr.status='active' AND (lower(pr.email)=lower(trim(p_identifier)) OR pr.id::text=trim(p_identifier) OR EXISTS(SELECT 1 FROM public.merchant_profiles mp WHERE mp.user_id=pr.id AND (lower(mp.merchant_slug)=lower(trim(p_identifier)) OR mp.merchant_id=trim(p_identifier))));
 IF p.id=auth.uid() THEN RAISE EXCEPTION 'Choose another merchant account.'; END IF;
 SELECT * INTO m FROM public.merchant_profiles WHERE user_id=p.id;
 RETURN jsonb_build_object('id',p.id,'name',coalesce(nullif(m.company_name,''),nullif(p.full_name,''),'ObPay merchant'),'username',coalesce(m.merchant_slug,m.merchant_id,p.id::text),'currencies',to_jsonb(array(SELECT DISTINCT c FROM unnest(coalesce(p.enabled_currencies,ARRAY[]::text[])||ARRAY[coalesce(p.default_currency,'UGX')]) c)));
END; $$;
REVOKE ALL ON FUNCTION public.find_transfer_recipient(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.find_transfer_recipient(text) TO authenticated;
CREATE FUNCTION public.transfer_between_merchants(p_recipient uuid,p_currency text,p_amount numeric,p_reason text,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE sender uuid:=auth.uid(); s public.profiles; r public.profiles; sw public.merchant_wallets; rw public.merchant_wallets; sb public.merchant_balances; rb public.merchant_balances; t public.merchant_transfers;
 sm text; rm text; wa numeric; ra numeric; available numeric; recipient_available numeric; wd numeric; md numeric; used numeric; sn text; rn text; ref text; curr text:=upper(p_currency); reason text:=trim(p_reason);
BEGIN
 IF sender IS NULL THEN RAISE EXCEPTION 'Please sign in again.'; END IF;
 IF p_recipient IS NULL OR sender=p_recipient THEN RAISE EXCEPTION 'Choose another merchant account.'; END IF;
 IF p_request_id IS NULL OR curr IS NULL OR curr NOT IN ('UGX','KES','RWF','NGN','XOF','USD','ZMW','SLL','CDF','XAF') OR p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount<=0 OR p_amount>1000000000000 THEN RAISE EXCEPTION 'Enter a valid transfer amount and wallet currency.'; END IF;
 IF p_amount<>round(p_amount,(CASE WHEN curr IN ('USD','NGN') THEN 2 ELSE 0 END)) THEN RAISE EXCEPTION 'Amount has too many decimal places for this wallet.'; END IF;
 IF reason IS NULL OR length(reason)<1 OR length(reason)>200 THEN RAISE EXCEPTION 'Enter a reason of up to 200 characters.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(least(sender::text,p_recipient::text),0));
 PERFORM pg_advisory_xact_lock(hashtextextended(greatest(sender::text,p_recipient::text),0));
 SELECT * INTO t FROM public.merchant_transfers WHERE sender_id=sender AND request_id=p_request_id;
 IF t.id IS NOT NULL THEN
 IF t.recipient_id<>p_recipient OR t.amount<>p_amount OR t.currency<>curr OR t.reason<>reason THEN RAISE EXCEPTION 'This transfer request was already used with different details.'; END IF;
 RETURN to_jsonb(t)||jsonb_build_object('duplicate',true);
 END IF;
 PERFORM id FROM public.profiles WHERE id IN (sender,p_recipient) ORDER BY id FOR UPDATE;
 SELECT * INTO s FROM public.profiles WHERE id=sender; SELECT * INTO r FROM public.profiles WHERE id=p_recipient;
 IF s.id IS NULL OR r.id IS NULL OR s.status IS DISTINCT FROM 'active' OR r.status IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'Both merchant accounts must be active.'; END IF;
 IF EXISTS(SELECT 1 FROM public.platform_settings WHERE maintenance_mode=true) THEN RAISE EXCEPTION 'Transfers are temporarily unavailable during maintenance.'; END IF;
 sm:=coalesce(s.default_currency,'UGX'); rm:=coalesce(r.default_currency,'UGX');
 IF NOT (curr=sm OR curr=ANY(coalesce(s.enabled_currencies,ARRAY[]::text[]))) OR NOT (curr=rm OR curr=ANY(coalesce(r.enabled_currencies,ARRAY[]::text[]))) THEN RAISE EXCEPTION 'Both merchants must enable the same currency wallet before transferring.'; END IF;
 PERFORM id FROM public.merchant_wallets WHERE user_id IN (sender,p_recipient) ORDER BY user_id FOR UPDATE;
 SELECT * INTO sw FROM public.merchant_wallets WHERE user_id=sender; SELECT * INTO rw FROM public.merchant_wallets WHERE user_id=p_recipient;
 IF sw.id IS NULL OR rw.id IS NULL THEN RAISE EXCEPTION 'Both accounts must have a wallet.'; END IF;
 IF sw.withdrawals_enabled IS FALSE THEN RAISE EXCEPTION 'Withdrawals are disabled on this account.'; END IF;
 used:=CASE WHEN sw.last_withdrawal_reset_at>now()-interval '24 hours' THEN coalesce(sw.last_24h_withdrawal_total,0) ELSE 0 END;
 IF coalesce(sw.daily_withdrawal_limit,0)>0 AND p_amount+used>sw.daily_withdrawal_limit THEN RAISE EXCEPTION 'Daily withdrawal limit exceeded.'; END IF;
 INSERT INTO public.merchant_balances(merchant_id,currency) SELECT u,curr FROM unnest(ARRAY[sender::text,p_recipient::text]) u ORDER BY u ON CONFLICT(merchant_id,currency) DO NOTHING;
 PERFORM id FROM public.merchant_balances WHERE merchant_id IN (sender::text,p_recipient::text) AND currency=curr ORDER BY merchant_id FOR UPDATE;
 SELECT * INTO sb FROM public.merchant_balances WHERE merchant_id=sender::text AND currency=curr; SELECT * INTO rb FROM public.merchant_balances WHERE merchant_id=p_recipient::text AND currency=curr;
 wa:=CASE WHEN curr=sm THEN coalesce(sw.available_balance,0) ELSE coalesce((sw.balances_by_currency->>curr)::numeric,0) END;
 ra:=CASE WHEN curr=rm THEN coalesce(rw.available_balance,0) ELSE coalesce((rw.balances_by_currency->>curr)::numeric,0) END;
 available:=wa+sb.available_balance; recipient_available:=ra+rb.available_balance;
 IF available<p_amount THEN RAISE EXCEPTION 'Insufficient % balance. Available: %.',curr,available; END IF;
 wd:=least(greatest(wa,0),p_amount); md:=p_amount-wd;
 UPDATE public.merchant_wallets SET available_balance=CASE WHEN curr=sm THEN coalesce(available_balance,0)-wd ELSE available_balance END,balances_by_currency=jsonb_set(coalesce(balances_by_currency,'{}'::jsonb),ARRAY[curr],to_jsonb(wa-wd)),last_24h_withdrawal_total=used+p_amount,last_withdrawal_reset_at=CASE WHEN last_withdrawal_reset_at>now()-interval '24 hours' THEN last_withdrawal_reset_at ELSE now() END,updated_at=now() WHERE id=sw.id;
 UPDATE public.merchant_balances SET available_balance=available_balance-md,updated_at=now() WHERE id=sb.id;
 UPDATE public.merchant_balances SET available_balance=available_balance+p_amount,updated_at=now() WHERE id=rb.id;
 SELECT coalesce(nullif(mp.company_name,''),nullif(s.full_name,''),'ObPay merchant') INTO sn FROM (SELECT 1) x LEFT JOIN public.merchant_profiles mp ON mp.user_id=sender;
 SELECT coalesce(nullif(mp.company_name,''),nullif(r.full_name,''),'ObPay merchant') INTO rn FROM (SELECT 1) x LEFT JOIN public.merchant_profiles mp ON mp.user_id=p_recipient;
 ref:='OBT_'||replace(p_request_id::text,'-','');
 INSERT INTO public.merchant_transfers(sender_id,recipient_id,request_id,reference,currency,amount,reason,sender_name,recipient_name,sender_balance_before,sender_balance_after,recipient_balance_before,recipient_balance_after) VALUES(sender,p_recipient,p_request_id,ref,curr,p_amount,reason,sn,rn,available,available-p_amount,recipient_available,recipient_available+p_amount) RETURNING * INTO t;
 INSERT INTO public.transactions(user_id,reference,amount,currency,status,type,payment_method,customer_name,description,fee_amount,net_amount,completed_at,metadata) VALUES(sender,ref||'_OUT',p_amount,curr,'success','transfer_out','obpay_transfer',rn,'Transfer to '||rn||' — '||reason,0,p_amount,now(),jsonb_build_object('transfer_id',t.id,'balance_before',available,'balance_after',available-p_amount,'wallet_debit',wd,'managed_debit',md)),(p_recipient,ref||'_IN',p_amount,curr,'success','transfer_in','obpay_transfer',sn,'Transfer from '||sn||' — '||reason,0,p_amount,now(),jsonb_build_object('transfer_id',t.id,'balance_before',recipient_available,'balance_after',recipient_available+p_amount));
 RETURN to_jsonb(t)||jsonb_build_object('duplicate',false);
END; $$;
REVOKE ALL ON FUNCTION public.transfer_between_merchants(uuid,text,numeric,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.transfer_between_merchants(uuid,text,numeric,text,uuid) TO authenticated;